/// <summary>
/// This is an event handler class for CustConfirmJour table
/// </summary>
class METCustConfirmJourTable_EventHandler
{
}

Method.Source:
/// <summary>
/// Updates the intergration status for the sales order confirmation
/// </summary>
/// <param name="args">CustConfirmJour args</param>
[PreHandlerFor(tableStr(CustConfirmJour), tableMethodStr(CustConfirmJour, insert))]
public static void CustConfirmJour_Post_insert(XppPrePostArgs args)
{
    CustConfirmJour custConfirmJour = args.getThis() as CustConfirmJour;
    CustConfirmJour custConfirm;

    METSalesTable metSalesTable = METSalesTable::findBySalesId(custConfirmJour.SalesId, true);

    if (metSalesTable && metSalesTable.ConfimRequired)
    {
        // If confirmation is required, force ORDD
        custConfirmJour.METALMPortalStage = METALMPortal::ORDD;
    }
    else
    {
        select firstonly RecId from custConfirm
            where custConfirm.SalesId == custConfirmJour.SalesId;

        // Otherwise, decide based on CustConfirm existence
        custConfirmJour.METALMPortalStage = custConfirm.RecId ? METALMPortal::BATC : METALMPortal::ORDD;
    }

}
